class Solution {
public:
    int minimumDeletions(string word, int k) {
        int freq[26] = {0};
        for (char c : word) freq[c - 'a']++;
        vector<int> f;
        for (int i = 0; i < 26; i++) if (freq[i] > 0) f.push_back(freq[i]);
        int ans = INT_MAX;
        for (int x : f) {
            int del = 0;
            for (int y : f) {
                if (y < x) del += y;
                else if (y > x + k) del += y - x - k;
            }
            ans = min(ans, del);
        }
        return ans == INT_MAX ? 0 : ans;
    }
};
